// Say something only when the state changes.
const SITE = 'your-site.example';
if (SITE === 'your-site.example') {
    node.warn('Set SITE in this function node to the name of your site first.');
    return null;
}
const failed = msg.error !== undefined || !msg.statusCode || msg.statusCode >= 400;
const down = flow.get('down') === true;
if (failed && !down) {
    flow.set('down', true);
    flow.set('downSince', Date.now());
    msg.payload = SITE + ' is DOWN (' + (msg.error ? msg.error.message : 'HTTP ' + msg.statusCode) + ').';
    return msg;
}
if (!failed && down) {
    const minutes = Math.round((Date.now() - flow.get('downSince')) / 60000);
    flow.set('down', false);
    msg.payload = SITE + ' is back after ' + minutes + ' minutes.';
    return msg;
}
return null;
